from functools import wraps

def convert(func):
    """
    Wrapper intended to convert results on the interface.py level
    from custom SchemaObject class objects to builtin types.

    When response is of type list its elements are first investigated
    and converted if needed.

    If response is of builtin type or if the object does not have
    attribute "to_dict" it is returned as is.

    If response is not of builtin type it is converted to dict.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        response = func(*args, **kwargs)

        try:
            if isinstance(response, list):
                return _handle_list_type_response(response=response)

            if _is_builtin_data_type(response):
                return response

            return _convert_response_to_dict(response=response)

        except AttributeError:
            return response

    return wrapper


def convert_result_to_builtin_type(cls):
    """
    Class decorator to convert results to builtin type
    of each callable and public method of the "vdu" class
    in interface.py
    """
    for attr_name, attr_value in cls.__dict__.items():
        if callable(attr_value) and not attr_name.startswith("_"):
            setattr(cls, attr_name, convert(attr_value))

    return cls


def _is_builtin_data_type(response):
    """
    Checks if the given response is one of the common built-in data types.
    """
    builtin_types = (
        int, float, str, bool, tuple, dict, list, set, type(None), bytes
    )
    return isinstance(response, builtin_types)


def _handle_list_type_response(response):
    """
    Recursive function to check elements of list response
    and convert them to builtin types if needed.
    """
    return_list = []
    for element in response:
        if isinstance(element, list):
            return_list.append(_handle_list_type_response(element))

        elif not _is_builtin_data_type(element):
            return_list.append(element.to_dict())

        else:
            return_list.append(element)

    return return_list


def _convert_response_to_dict(response):
    """
    Converts dict and all its items which are not of builtin
    type to dictionary
    """
    response_dict = response.to_dict()
    for key, value in response_dict.items():
        if isinstance(value, list):
            response_dict[key] = _handle_list_type_response(response=value)

    return response_dict
